const volumeSnapshotBlocksPending = `-- name: VolumeSnapshotBlocksPending :one
SELECT EXISTS (
 SELECT 1 FROM ebs_snapshots
 WHERE volume_source_partition = ?1
  AND volume_source_account_id = ?2
  AND volume_source_region = ?3
  AND volume_source_id = ?4 AND blocks_work_at IS NOT NULL
)
`

type VolumeSnapshotBlocksPendingParams struct {
	Partition string
	AccountID string
	Region    string
	ID        string
}

func (q *Queries) VolumeSnapshotBlocksPending(ctx context.Context, arg VolumeSnapshotBlocksPendingParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, volumeSnapshotBlocksPending,
		arg.Partition,
		arg.AccountID,
		arg.Region,
		arg.ID,
	)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
